function cwCalculate(){
  const keyBase=calculatorKey.replace(/\.html$/,'');
  const pageBase=currentPage.replace(/\.html$/,'');
  const candidates=[calculatorKey, keyBase+'.html', currentPage, pageBase+'.html', currentPage.replace('-calculator.html','.html')];
  const fn=candidates.map(k=>calculatorConfigs[k]).find(Boolean);
  const fields=Array.from(document.querySelectorAll('input, select, textarea'));
  const invalid=fields.find(el=>el.type==='number' && el.value!=='' && (el.validity && !el.validity.valid));
  if(invalid){out(cwText('Check the highlighted input.'));if(invalid.reportValidity)invalid.reportValidity();return;}
  if(fn) fn();
}
if(calculateBtn&&resetBtn){
  calculateBtn.addEventListener('click',cwCalculate);
  resetBtn.addEventListener('click',resetCalculator);
  document.querySelectorAll('input, select').forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();cwCalculate();}}));
}

