/* Shared, audited implementations. All calculator pages retain calculatorConfigs. */
function cwLoanInputs(){return {loan:Number.isFinite(n('loan'))?n('loan'):n('feet'),rate:Number.isFinite(n('rate'))?n('rate'):n('inches'),years:$('years')?n('years'):n('decimals')};}
function cwMonthly(loan,apr,years){
 if(![loan,apr,years].every(Number.isFinite)||loan<=0||apr<0||years<=0||years>100)return NaN;
 const r=apr/1200,m=Math.round(years*12);if(m<1)return NaN;
 return r===0?loan/m:loan*r/(-Math.expm1(-m*Math.log1p(r)));
}
function cwPayoff(balance,apr,payment){
 if(![balance,apr,payment].every(Number.isFinite)||balance<=0||apr<0||payment<=0||payment<=balance*apr/1200)return null;
 let interest=0,months=0;const rows=[];
 while(balance>0.0000001&&months<1200){const i=balance*apr/1200,paid=Math.min(payment,balance+i),principal=paid-i;balance=Math.max(0,balance-principal);interest+=i;months++;rows.push({month:months,interest:i,principal,balance});}
 return balance>0.0000001?null:{months,interest,rows};
}
function cwMortgage(){
 const v=cwLoanInputs(),p=cwMonthly(v.loan,v.rate,v.years);if(!Number.isFinite(p))return out('Enter a positive loan amount, a non-negative rate, and a term of up to 100 years.');
 const m=Math.round(v.years*12);out('Monthly payment: '+money(p)+' • Total interest: '+money(Math.max(0,p*m-v.loan))+' • Total paid: '+money(p*m));
 const key=calculatorKey.replace(/\.html$/,'');
 if(['mortgage-amortization','amortization-calculator','mortgage-amortization-calculator'].includes(key))cwSchedule(cwPayoff(v.loan,v.rate,p));
}
function cwSchedule(payoff){
 const old=$('cwSchedule');if(old)old.remove();if(!payoff)return;
 const years=[];payoff.rows.forEach(row=>{const k=Math.floor((row.month-1)/12);if(!years[k])years[k]={principal:0,interest:0,balance:0};years[k].principal+=row.principal;years[k].interest+=row.interest;years[k].balance=row.balance;});
 const section=document.createElement('div');section.id='cwSchedule';section.className='cw-table-wrap';
 section.innerHTML='<table><caption>'+cwText('Yearly amortization summary')+'</caption><thead><tr>'+['Year','Principal','Interest','Remaining balance'].map(x=>'<th scope="col">'+cwText(x)+'</th>').join('')+'</tr></thead><tbody>'+years.map((y,i)=>'<tr><th scope="row">'+(i+1)+'</th><td>'+money(y.principal)+'</td><td>'+money(y.interest)+'</td><td>'+money(y.balance)+'</td></tr>').join('')+'</tbody></table>';
 const card=document.querySelector('.calculator-card');if(card)card.appendChild(section);
}
function cwExtra(){
 const v=cwLoanInputs(),base=cwMonthly(v.loan,v.rate,v.years),extra=$('extra')&&$('extra').value.trim()!==''?n('extra'):0;
 if(!Number.isFinite(base)||!Number.isFinite(extra)||extra<0)return out('Enter a valid loan, rate, term and non-negative extra payment.');
 const result=cwPayoff(v.loan,v.rate,base+extra);if(!result)return out('Payment does not repay the balance within 100 years.');
 out('Standard payment: '+money(base)+' • With extra: '+money(base+extra)+' • Estimated payoff: '+monthsToText(result.months)+' • Interest saved: '+money(Math.max(0,base*Math.round(v.years*12)-v.loan-result.interest))+' • Time saved: '+monthsToText(Math.max(0,Math.round(v.years*12)-result.months)));
}
function cwSingleDebt(){const balance=$('loan')?n('loan'):$('balance')?n('balance'):n('feet'),apr=$('rate')?n('rate'):n('inches'),payment=$('payment')?n('payment'):n('decimals'),result=cwPayoff(balance,apr,payment);if(!result)return out('Enter a payment above monthly interest that repays the balance within 100 years.');out('Estimated payoff: '+monthsToText(result.months)+' • Estimated interest: '+money(result.interest)+' • Total paid: '+money(balance+result.interest));}
function cwDebtStrategy(strategy){
 const list=$('debts'),raw=list?list.value.trim():'';if(!raw)return cwSingleDebt();
 const debts=raw.split(/\n+/).filter(x=>x.trim()).map((row,i)=>{const a=row.split(',').map(x=>x.trim());return {name:a[0]||String(i+1),balance:Number(a[1]),apr:Number(a[2]),min:Number(a[3]),valid:a.length===4&&a.slice(1).every(x=>x!==''),order:i};});
 const budget=$('payment')?n('payment'):n('decimals');
 if(debts.length>50||debts.some(d=>!d.valid||![d.balance,d.apr,d.min].every(Number.isFinite)||d.balance<=0||d.apr<0||d.min<=0)||!Number.isFinite(budget)||budget<=0)return out('Enter up to 50 valid debt rows and a positive monthly budget.');
 if(budget+1e-8<debts.reduce((a,d)=>a+d.min,0))return out('Monthly budget must cover all entered minimum payments.');
 let interest=0,month=0;const order=[];
 while(debts.some(d=>d.balance>1e-7)&&month<1200){month++;for(const d of debts){if(d.balance<=1e-7)continue;const i=d.balance*d.apr/1200;d.balance+=i;interest+=i;}
 let left=budget;for(const d of debts){const paid=Math.min(d.balance,d.min);d.balance=Math.max(0,d.balance-paid);left-=paid;if(d.balance<=1e-7&&!order.includes(d.name))order.push(d.name);}
 const active=debts.filter(d=>d.balance>1e-7).sort((a,b)=>strategy==='snowball'?a.balance-b.balance||b.apr-a.apr||a.order-b.order:b.apr-a.apr||a.balance-b.balance||a.order-b.order);
 for(const d of active){const paid=Math.min(d.balance,Math.max(0,left));d.balance=Math.max(0,d.balance-paid);left-=paid;if(d.balance<=1e-7&&!order.includes(d.name))order.push(d.name);}}
 if(debts.some(d=>d.balance>1e-7))return out('Payment does not repay the balance within 100 years.');
 out((strategy==='snowball'?'Snowball':'Avalanche')+' • Estimated payoff: '+monthsToText(month)+' • Estimated interest: '+money(interest)+' • Payoff order: '+order.join(' → '));
}
